extends RefCounted
class_name SaveManager

func _normalize_path(path: String, binary: bool) -> String:
	var ext = ".res" if binary else ".tres"
	if path.get_extension() != ext.substr(1):
		path += ext
	return path

func save_to_disk(data: GameSaveData, path: String, binary: bool) -> int:
	var final_path = _normalize_path(path, binary)
	var err = ResourceSaver.save(data, final_path)
	return err

func load_from_disk(path: String) -> GameSaveData:
	var ext = path.get_extension()
	if ext == "res" or ext == "tres":
		return ResourceLoader.load(path) as GameSaveData
	var tres_path = path + ".tres"
	var res_path = path + ".res"
	if FileAccess.file_exists(tres_path):
		return ResourceLoader.load(tres_path) as GameSaveData
	elif FileAccess.file_exists(res_path):
		return ResourceLoader.load(res_path) as GameSaveData
	return null

func compute_hash(data: GameSaveData) -> String:
	var ctx = HashingContext.new()
	ctx.start(HashingContext.HASH_SHA256)
	ctx.update(str(data.player_position).to_utf8_buffer())
	ctx.update(str(data.last_played).to_utf8_buffer())
	ctx.update(str(data.unlocked_levels).to_utf8_buffer())
	for item in data.inventory:
		ctx.update(str(item.id).to_utf8_buffer())
		ctx.update(str(item.quantity).to_utf8_buffer())
		ctx.update(str(item.rarity).to_utf8_buffer())
	return ctx.finish().hex_encode().to_lower()

